  4295  /* Match against an fnmatch(3) pattern or regular expression. */
  4296  static char *
  4297  format_match(struct format_modifier *fm, const char *pattern, const char *text)
  4298  {
  4299          const char      *s = "";
  4300          regex_t          r;
  4301          int              flags = 0;
  4302
  4303          if (fm->argc >= 1)
  4304                  s = fm->argv[0];
  4305          if (strchr(s, 'r') == NULL) {
  4306                  if (strchr(s, 'i') != NULL)
  4307                          flags |= FNM_CASEFOLD;
  4308                  if (fnmatch(pattern, text, flags) != 0)
  4309                          return (xstrdup("0"));
  4310          } else {
  4311                  flags = REG_EXTENDED|REG_NOSUB;
  4312                  if (strchr(s, 'i') != NULL)
  4313                          flags |= REG_ICASE;
  4314                  if (regcomp(&r, pattern, flags) != 0)
  4315                          return (xstrdup("0"));
  4316                  if (regexec(&r, text, 0, NULL, 0) != 0) {
  4317                          regfree(&r);
  4318                          return (xstrdup("0"));
  4319                  }
  4320                  regfree(&r);
  4321          }
  4322          return (xstrdup("1"));
  4323  }
  4324
  4325  /* Perform substitution in string. */
  4326  static char *
  4327  format_sub(struct format_modifier *fm, const char *text, const char *pattern,
  4328      const char *with)
  4329  {
  4330          char    *value;
  4331          int      flags = REG_EXTENDED;
  4332
  4333          if (fm->argc >= 3 && strchr(fm->argv[2], 'i') != NULL)
  4334                  flags |= REG_ICASE;
  4335          value = regsub(pattern, with, text, flags);
  4336          if (value == NULL)
  4337                  return (xstrdup(text));
  4338          return (value);
  4339  }
