  4430  /* Loop over sessions. */
  4431  static char *
  4432  format_loop_sessions(struct format_expand_state *es, const char *fmt)
  4433  {
  4434          struct sort_criteria             *sc = &sort_crit;
  4435          struct format_tree               *ft = es->ft;
  4436          struct client                    *c = ft->client;
  4437          struct cmdq_item                 *item = ft->item;
  4438          struct format_tree               *nft;
  4439          struct format_expand_state        next;
  4440          char                             *all, *active, *use, *expanded, *value;
  4441          size_t                            valuelen;
  4442          struct session                   *s, **l;
  4443          int                               i, n, last = 0;
  4444
  4445          if (format_choose(es, fmt, &all, &active, 0) != 0) {
  4446                  all = xstrdup(fmt);
  4447                  active = NULL;
  4448          }
  4449
  4450          value = xcalloc(1, 1);
  4451          valuelen = 1;
  4452
  4453          l = sort_get_sessions(&n, sc);
  4454          for (i = 0; i < n; i++) {
  4455                  s = l[i];
  4456                  format_log(es, "session loop: $%u", s->id);
  4457                  if (active != NULL &&
  4458                      ft->c != NULL &&
  4459                      s->id == ft->c->session->id)
  4460                          use = active;
  4461                  else
  4462                          use = all;
  4463                  if (i == n - 1)
  4464                          last = FORMAT_LAST;
  4465                  nft = format_create(c, item, FORMAT_NONE, ft->flags|last);
  4466                  format_defaults(nft, ft->c, s, NULL, NULL);
  4467                  format_copy_state(&next, es, 0);
  4468                  next.ft = nft;
  4469                  expanded = format_expand1(&next, use);
  4470                  format_free(next.ft);
  4471
  4472                  valuelen += strlen(expanded);
  4473                  value = xrealloc(value, valuelen);
  4474
  4475                  strlcat(value, expanded, valuelen);
  4476                  free(expanded);
  4477          }
  4478
  4479          free(active);
  4480          free(all);
  4481
  4482          return (value);
  4483  }
