  4509  /* Add neighbor window variables to the format tree. */
  4510  static void
  4511  format_add_window_neighbor(struct format_tree *nft, struct winlink *wl,
  4512      struct session *s, const char *prefix)
  4513  {
  4514          struct options_entry    *o;
  4515          const char              *oname;
  4516          char                    *key, *prefixed, *oval;
  4517
  4518          xasprintf(&key, "%s_window_index", prefix);
  4519          format_add(nft, key, "%u", wl->idx);
  4520          free(key);
  4521
  4522          xasprintf(&key, "%s_window_active", prefix);
  4523          format_add(nft, key, "%d", wl == s->curw);
  4524          free(key);
  4525
  4526          o = options_first(wl->window->options);
  4527          while (o != NULL) {
  4528                  oname = options_name(o);
  4529                  if (*oname == '@') {
  4530                          xasprintf(&prefixed, "%s_%s", prefix, oname);
  4531                          oval = options_to_string(o, -1, 1);
  4532                          format_add(nft, prefixed, "%s", oval);
  4533                          free(oval);
  4534                          free(prefixed);
  4535                  }
  4536                  o = options_next(o);
  4537          }
  4538  }
