  4553          struct window                    *w;
  4554          int                               i, n, last = 0;
  4555
  4556          if (ft->s == NULL) {
  4557                  format_log(es, "window loop but no session");
  4558                  return (NULL);
  4559          }
  4560
  4561          if (format_choose(es, fmt, &all, &active, 0) != 0) {
  4562                  all = xstrdup(fmt);
  4563                  active = NULL;
  4564          }
  4565
  4566          value = xcalloc(1, 1);
  4567          valuelen = 1;
  4568
  4569          l = sort_get_winlinks_session(ft->s, &n, sc);
  4570          for (i = 0; i < n; i++) {
  4571                  wl = l[i];
  4572                  w = wl->window;
  4573                  format_log(es, "window loop: %u @%u", wl->idx, w->id);
  4574                  if (active != NULL && wl == ft->s->curw)
  4575                          use = active;
  4576                  else
  4577                          use = all;
  4578                  if (i == n - 1)
  4579                          last = FORMAT_LAST;
