  4594                  format_copy_state(&next, es, 0);
  4595                  next.ft = nft;
  4596                  expanded = format_expand1(&next, use);
  4597                  format_free(nft);
  4598
  4599                  valuelen += strlen(expanded);
  4600                  value = xrealloc(value, valuelen);
  4601
  4602                  strlcat(value, expanded, valuelen);
  4603                  free(expanded);
  4604          }
  4605
  4606          free(active);
  4607          free(all);
  4608
  4609          return (value);
  4610  }
