  5045                                  if (strchr(fm->argv[0], 'i') != NULL)
  5046                                          sc->order = SORT_ORDER;
  5047                                  else if (strchr(fm->argv[0], 'n') != NULL)
  5048                                          sc->order = SORT_NAME;
  5049                                  else if (strchr(fm->argv[0], 't') != NULL)
  5050                                          sc->order = SORT_ACTIVITY;
  5051                                  else
  5052                                          sc->order = SORT_ORDER;
